<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { apiGet, apiPatch } from '../api/client'
import KpiGrid from '../components/KpiGrid.vue'; import PageHeader from '../components/PageHeader.vue'; import type { FuelData } from '../types/admin'
import { useAuthStore } from '../stores/auth'
const auth=useAuthStore()
const data=ref<FuelData>({prices:[],stations:[]}); const loading=ref(true); const tab=ref('prices'); const dialog=ref(false); const form=ref({id:'',grade:'',price:0,change:0})
const kpis=computed(()=>[{label:'油价记录',value:data.value.prices.length,delta:'城市+油号'},{label:'加油站',value:data.value.stations.length,delta:'已录入'},{label:'营业中',value:data.value.stations.filter(x=>x.enabled).length,delta:'当前启用'},{label:'停用站点',value:data.value.stations.filter(x=>!x.enabled).length,delta:'需核查',warn:true}])
async function load(){loading.value=true;try{data.value=await apiGet<FuelData>('/admin/fuel')}finally{loading.value=false}}
function editPrice(tableRow:unknown){const row=tableRow as FuelData['prices'][number];form.value={id:row.id,grade:row.grade,price:row.price,change:row.change};dialog.value=true}
async function savePrice(){await apiPatch(`/admin/fuel/prices/${form.value.id}`,{price:form.value.price,change:form.value.change});dialog.value=false;ElMessage.success('油价已更新并同步小程序');await load()}
async function toggleStation(tableRow:unknown){const row=tableRow as FuelData['stations'][number];try{await apiPatch(`/admin/fuel/stations/${row.id}`,{enabled:row.enabled});ElMessage.success('站点状态已保存')}catch{row.enabled=!row.enabled}}
onMounted(load)
</script>
<template><PageHeader title="加油站与油价" group="路线运营" description="油价与站点数据直接供小程序加油页使用"><el-button :loading="loading" @click="load">刷新</el-button></PageHeader><KpiGrid :items="kpis" :loading="loading"/><section class="panel"><el-tabs v-model="tab" class="panel__body"><el-tab-pane label="油价维护" name="prices"><el-table :data="data.prices" v-loading="loading"><el-table-column label="城市"><template #default="{row}">{{row.city.name}}</template></el-table-column><el-table-column prop="grade" label="油号"/><el-table-column label="单价"><template #default="{row}"><strong>¥ {{row.price.toFixed(2)}}</strong></template></el-table-column><el-table-column label="较昨日"><template #default="{row}"><span :style="{color:row.change>0?'#c33':row.change<0?'#4b7f2b':'#777'}">{{row.change>0?'+':''}}{{row.change.toFixed(2)}}</span></template></el-table-column><el-table-column label="更新时间"><template #default="{row}">{{new Date(row.publishedAt).toLocaleString('zh-CN',{hour12:false})}}</template></el-table-column><el-table-column v-if="auth.hasPermission('fuel:write')" label="操作" width="100"><template #default="{row}"><el-button size="small" type="primary" @click="editPrice(row)">编辑</el-button></template></el-table-column></el-table></el-tab-pane><el-tab-pane label="加油站管理" name="stations"><el-table :data="data.stations" v-loading="loading"><el-table-column prop="name" label="站点" min-width="240"/><el-table-column prop="brand" label="品牌" width="100"/><el-table-column label="城市" width="100"><template #default="{row}">{{row.city.name}}</template></el-table-column><el-table-column prop="address" label="地址" min-width="220"/><el-table-column prop="openingHours" label="营业时间" width="130"/><el-table-column label="92 / 95" width="120"><template #default="{row}">{{row.price92}} / {{row.price95}}</template></el-table-column><el-table-column label="启用" width="90"><template #default="{row}"><el-switch v-model="row.enabled" :disabled="!auth.hasPermission('fuel:write')" @change="toggleStation(row)"/></template></el-table-column></el-table></el-tab-pane></el-tabs></section><el-dialog v-model="dialog" title="维护油价" width="440px"><el-form label-position="top"><el-form-item label="油号"><el-input :model-value="form.grade" disabled/></el-form-item><el-form-item label="当前单价"><el-input-number v-model="form.price" :precision="2" :step="0.01" :min="0" :max="30"/></el-form-item><el-form-item label="较昨日涨跌"><el-input-number v-model="form.change" :precision="2" :step="0.01" :min="-10" :max="10"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button v-if="auth.hasPermission('fuel:write')" type="primary" @click="savePrice">保存</el-button></template></el-dialog></template>
